import {CATEGORIES,CONDITIONS,SEED,SAMPLE_EMAIL,SAMPLE_PASSWORD,filterItems,validateLogin,validatePost} from './model.mjs';
import {art} from './art.mjs';
const app=document.getElementById('app'),sheet=document.getElementById('sheet'),toastEl=document.getElementById('toast');
const KEY='student-exchange-phone-v1';
const paths={swap:'<path d="M4 8h16l-4-4M20 16H4l4 4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',heart:'<path d="M20.8 4.7a5.5 5.5 0 0 0-7.8 0L12 5.8l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.5a5.5 5.5 0 0 0 0-7.8Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',message:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H9l-5 2v-5a8.5 8.5 0 1 1 17-5.5Z"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',filter:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="10" cy="18" r="2" fill="currentColor"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',box:'<path d="m3 7 9-4 9 4v11l-9 4-9-4V7Zm0 0 9 5 9-5M12 12v10"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v14H3V7Z"/><circle cx="12" cy="13" r="4"/>',check:'<path d="m5 12 4 4L20 5"/>',logout:'<path d="M9 21H4V3h5M10 12h11m-5-5 5 5-5 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.1"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',book:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3V4Zm9 2v16"/>',home:'<path d="m3 10 9-7 9 7v11h-7v-7h-4v7H3V10Z"/>',star:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>'};
const icon=(name,size=22,fill=false)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="${fill?'currentColor':'none'}" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.box}</svg>`;
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={items:[],saved:[],profile:{name:'Alex',school:'CU Denver',location:'Auraria campus'},threads:[],session:false};
try{const d=JSON.parse(localStorage.getItem(KEY)||'null');if(d&&Array.isArray(d.items)&&Array.isArray(d.saved)&&d.profile&&Array.isArray(d.threads))data=d;}catch{}
let storageFailed=false;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(data));return true;}catch{storageFailed=true;toast('Storage is unavailable or full. Changes stay in this session only.');return false;}}
const items=()=>[...data.items,...SEED];
let screen='splash',page='browse',step=0,query='',filters={category:'All',min:'',max:'',conditions:[]},draftPhotos=[],currentDetail=null,toastTimer,startTimer,returnFocus=null;
const brand=()=>`<div class="brand"><span class="logo">${icon('swap',23)}</span><span>student<em>exchange</em></span></div>`;
const artBooks=()=>`<div class="hero-art" aria-hidden="true"><div class="mini-book">SECOND SEMESTER<b>Pass<br>it on.</b>STUDENT EXCHANGE</div><div class="mini-book gold">A GOOD FIND<b>New<br>chapter.</b>MAKE IT YOURS</div><div class="art-swap">${icon('swap',24)}</div></div>`;
function toast(text){clearTimeout(toastTimer);toastEl.textContent=text;toastEl.classList.add('visible');toastTimer=setTimeout(()=>toastEl.classList.remove('visible'),3500);}
function enter(){clearTimeout(startTimer);data.session=true;persist();screen='app';page='browse';render();}
function go(p){page=p;screen='app';render();window.scrollTo({top:0,behavior:'instant'});}
function modal(title,body){returnFocus=document.activeElement;sheet.innerHTML=`<div class="sheet-header"><h2 id="sheet-title">${title}</h2><button type="button" class="icon-btn flat" data-action="close" aria-label="Close">${icon('close')}</button></div><div class="sheet-body">${body}</div>`;if(!sheet.open)sheet.showModal();}
sheet.addEventListener('close',()=>{currentDetail=null;if(returnFocus?.isConnected)returnFocus.focus();});
function close(){sheet.close();}
function render(){
 if(screen==='splash'){app.innerHTML=`<main class="intro-screen splash"><div class="logo">${icon('swap',38)}</div><h1>Student Exchange</h1><p>Good things come around.</p><div class="loader" role="status" aria-label="Starting prototype"></div></main>`;return;}
 if(screen==='welcome'){const titles=['Your campus.<br>Your exchange.','Pass it on.<br>Pick it up.','Good finds.<br>Great connections.'];const descriptions=['A little less spending. A little more student life. Find a new home for the things you love.','Give your books, tech, and essentials a second semester. Browse finds from your campus community.','Save your favorites, try posting an item, and explore your own campus marketplace demo.'];app.innerHTML=`<main class="intro-screen"><div class="intro-top">${brand()}<button class="text-btn" data-action="login">Skip</button></div><div class="intro-art"><div class="art-circle"></div>${artBooks()}<div class="floating-label">Less waste. More possibilities.</div></div><p class="eyebrow">MADE FOR YOUR NEXT CHAPTER</p><h1>${titles[step]}</h1><p class="intro-body">${descriptions[step]}</p><div class="intro-footer"><div class="dots">${titles.map((_,i)=>`<button class="dot-btn ${step===i?'active':''}" data-action="slide" data-index="${i}" aria-label="Welcome page ${i+1} of 3" aria-pressed="${step===i}"><i></i></button>`).join('')}</div><button class="primary block" data-action="next">${step===2?'Get started':'Continue'} ${icon('arrow',18)}</button><button class="text-btn block" data-action="login">Already here? Log in</button><p class="fine">Interactive prototype · Sample data, real interactions</p></div></main>`;return;}
 if(screen==='login'){app.innerHTML=`<main class="intro-screen login"><div class="intro-top"><button class="icon-btn flat" data-action="welcome" aria-label="Back to welcome">${icon('back')}</button><span class="tag">MOBILE DEMO</span></div><div class="login-brand">${brand()}</div><p class="eyebrow">YOUR CAMPUS CONNECTION</p><h1>Welcome back.</h1><p class="intro-body">Your next great find is just around the corner.</p><form id="login-form" novalidate><div id="login-error" role="alert"></div><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" autocapitalize="none" placeholder="you@university.edu" required></div><div class="field"><div class="label-row"><label for="password">Password</label><button type="button" class="text-btn" data-action="reset-password">Forgot password?</button></div><div class="password-field"><input id="password" name="password" type="password" autocomplete="current-password" placeholder="Enter your password" required><button type="button" class="text-btn" data-action="show-password" aria-label="Show password">Show</button></div></div><button class="primary block" type="submit">Log in ${icon('arrow',18)}</button></form><div class="login-box"><strong>Take it for a test drive.</strong><p>No real credentials needed. This prototype uses a public sample account.</p><button class="text-btn" data-action="fill-demo">Fill demo account</button></div><button class="secondary block" data-action="enter">Explore without logging in ${icon('arrow',17)}</button><p class="fine">Demo login only. Your existing website account is not connected.<br>No password is stored or sent.</p></main>`;return;}
 let content=page==='browse'?browse():page==='saved'?saved():page==='account'?account():page==='mine'?mine():inbox();
 app.innerHTML=`<header class="app-header"><div class="wrap header-main">${brand()}<div class="header-actions"><button class="primary desktop-post" data-action="post">${icon('plus',19)} Post an item</button><button class="icon-btn flat" data-action="about" aria-label="About this prototype">${icon('info',21)}</button><button class="icon-btn avatar" data-action="nav" data-page="account" aria-label="Account">${E(data.profile.name[0]||'A')}</button></div></div></header><div class="demo-strip"><span class="demo-dot"></span>Prototype · Sample listings · Your changes stay on this device</div><main class="wrap content">${content}</main><nav class="bottom-nav" aria-label="Main navigation">${[['browse','home','Explore'],['saved','heart','Saved'],['post','plus','Post'],['inbox','message','Inbox'],['account','user','Account']].map(([p,i,label])=>`<button class="nav-btn ${page===p?'active':''} ${p==='post'?'post':''}" data-action="${p==='post'?'post':'nav'}" ${p!=='post'?`data-page="${p}"`:''} ${page===p?'aria-current="page"':''}><span>${icon(i,22)}</span>${label}${p==='saved'&&data.saved.length?`<b class="badge">${data.saved.length}</b>`:''}</button>`).join('')}</nav>`;
 if(page==='browse'){const input=document.getElementById('search-input');input.value=query;input.addEventListener('input',e=>{query=e.target.value;updateResults();});}
}
function itemCard(i){const isSaved=data.saved.includes(i.id);return `<article class="item"><button class="item-open" data-action="detail" data-id="${E(i.id)}" aria-label="View ${E(i.title)}, $${E(i.price)}"><div class="item-art">${picture(i)}${i.own?'':`<span class="sample-tag">SAMPLE</span>`}</div><div class="item-price">${money(i.price)}</div><p class="item-title">${E(i.title)}</p><div class="item-meta">${icon('pin',11)} ${E(i.location)} <span>· ${E(i.age||'Just now')}</span></div></button><button class="save ${isSaved?'saved':''}" data-action="save" data-id="${E(i.id)}" aria-label="${isSaved?'Unsave':'Save'} ${E(i.title)}" aria-pressed="${isSaved}">${icon('heart',19,isSaved)}</button></article>`;}
function picture(i){return i.photos?.length?`<img src="${E(i.photos[0])}" alt="${E(i.title)}">`:art(i.kind||'other',i.tone||'sage');}
const money=p=>Number(p)===0?'Free':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(p).replace('.00','');
function results(){return filterItems(items().filter(i=>!i.sold),{...filters,query});}
function browse(){return `<section class="hero"><div><p class="eyebrow">YOUR CAMPUS. YOUR COMMUNITY.</p><h1>Good finds.<br>Better together.</h1><p>Buy less new. Make room for more.</p></div>${artBooks()}</section><div class="search-row"><label class="search">${icon('search',20)}<span class="sr-only">Search listings</span><input type="search" id="search-input" placeholder="What are you looking for?" autocomplete="off"></label><button class="secondary filter-btn" data-action="filters" aria-label="Open filters">${icon('filter',19)} Filters ${activeFilterCount()?`<span class="filter-count">${activeFilterCount()}</span>`:''}</button></div><div class="categories" aria-label="Categories">${CATEGORIES.map(c=>`<button class="pill ${filters.category===c?'active':''}" data-action="category" data-category="${E(c)}" aria-pressed="${filters.category===c}">${E(c==='All'?'All finds':c)}</button>`).join('')}</div><div class="section-row"><h2>Fresh on campus</h2><span id="results-count" class="muted" aria-live="polite">${results().length} ${results().length===1?'find':'finds'}</span></div><div id="results-grid" class="grid">${results().map(itemCard).join('')}</div><div id="results-empty" ${results().length?'hidden':''}>${empty('No finds just yet.','Try another search or loosen your filters.','search')}</div>`;}
function updateResults(){const r=results();document.getElementById('results-grid').innerHTML=r.map(itemCard).join('');document.getElementById('results-count').textContent=`${r.length} ${r.length===1?'find':'finds'}`;document.getElementById('results-empty').hidden=r.length>0;}
function activeFilterCount(){return (filters.min!==''||filters.max!==''?1:0)+filters.conditions.length;}
function empty(title,body,i='heart'){return `<div class="empty"><div class="empty-icon">${icon(i,28)}</div><h2>${title}</h2><p>${body}</p><button class="primary" data-action="nav" data-page="browse">Explore campus finds ${icon('arrow',17)}</button></div>`;}
function saved(){const found=items().filter(i=>data.saved.includes(i.id));return `<p class="eyebrow">YOUR LITTLE COLLECTION</p><h1>Saved for later.</h1><p class="muted small">The things that caught your eye, all in one place.</p><div class="section-row" style="margin-top:26px"><h2>Quick save</h2><span class="muted">${found.length} ${found.length===1?'item':'items'}</span></div>${found.length?`<div class="grid">${found.map(itemCard).join('')}</div>`:empty('Keep the good finds close.','Tap the heart on any listing to save it here.')}`;}
function mine(){return `<p class="eyebrow">YOUR CAMPUS SHOP</p><h1>My items.</h1><p class="muted small">Listings you create here are saved on this device only.</p><button class="primary" data-action="post">${icon('plus',18)} Post an item</button>${data.items.length?`<div class="grid" style="margin-top:25px">${data.items.map(i=>`<div>${itemCard(i)}<p class="small muted">${i.sold?'Marked as sold':'Available'} · Local demo listing</p></div>`).join('')}</div>`:empty('Make a little room.','Try posting a textbook, tech, or something you no longer need.','box')}`;}
function account(){return `<p class="eyebrow">A LITTLE SPACE OF YOUR OWN</p><h1>Hey, ${E(data.profile.name)}.</h1><p class="muted small">Welcome to your campus exchange.</p><section class="account-card"><div class="profile-row"><div class="profile-big">${E(data.profile.name[0]||'A')}</div><div><h2>${E(data.profile.name)}</h2><span class="location">${icon('pin',13)} ${E(data.profile.school)}</span></div></div><div class="list-actions">${[['mine','box','My items',data.items.length],['saved','heart','Saved items',data.saved.length],['profile','user','Account settings',''],['about','info','About this prototype',''],['install','home','Add to Home Screen','']].map(([p,i,t,n])=>`<button class="list-action" data-action="${['mine','saved'].includes(p)?'nav':p}" data-page="${p}"><span>${icon(i,20)} ${t}</span><span>${n} ${icon('chevron',16)}</span></button>`).join('')}<button class="list-action danger" data-action="logout"><span>${icon('logout',20)} Log out of demo</span>${icon('chevron',16)}</button></div></section><div class="info">${icon('info',16)} This is a local prototype. Your listings, saved items, profile edits, and practice messages stay in this browser. They are not visible to other people.</div><button class="text-btn danger" data-action="reset">Reset prototype data</button>`;}
function inbox(){return `<p class="eyebrow">KEEP THE CONVERSATION GOING</p><h1>Your inbox.</h1><p class="muted small">Practice conversations only. Messages are never sent to sellers.</p><div class="messages">${data.threads.length?data.threads.map(t=>`<button class="message-row block" data-action="thread" data-id="${E(t.id)}" style="text-align:left"><div class="profile-big">${E(t.seller[0])}</div><div><h3>${E(t.title)}</h3><p>${E(t.messages.at(-1)||'Start a practice conversation')}</p><span class="tag" style="display:inline-block;margin-top:8px">DEMO CHAT</span></div></button>`).join(''):empty('Say hello to a good find.','Open a sample listing and tap “Try messaging” to test a conversation.','message')}</div>`;}
function detail(id){const i=items().find(x=>x.id===id);if(!i)return;currentDetail=id;modal(i.own?'Your listing':'Campus find',`<div class="detail-art">${picture(i)}</div><div class="detail-price">${money(i.price)}</div><h3 class="detail-title">${E(i.title)}</h3><div class="tag-row"><span class="tag">${E(i.condition)}</span><span class="tag">${E(i.category)}</span>${i.sold?'<span class="tag">Sold</span>':''}</div><p class="location">${icon('pin',15)} ${E(i.location)}</p><p class="description">${E(i.description||'No description provided.')}</p><div class="seller"><div class="icon-btn avatar">${E((i.seller||data.profile.name)[0])}</div><div><strong>${E(i.seller||data.profile.name)}</strong><br><span class="muted small">${i.own?'Your local demo listing':'Sample seller · Not a real listing'}</span></div></div>${i.own?`<div class="detail-actions"><button class="primary" data-action="sold" data-id="${E(id)}">${i.sold?'Mark available':'Mark as sold'}</button><button class="icon-btn danger" data-action="delete" data-id="${E(id)}" aria-label="Delete this demo listing">${icon('trash')}</button></div>`:`<div class="info">Sample listing. No payments or real purchases can be made.</div><div class="detail-actions"><button class="primary" data-action="start-thread" data-id="${E(id)}">${icon('message',20)} Try messaging</button><button class="secondary" data-action="detail-save" data-id="${E(id)}" aria-label="${data.saved.includes(id)?'Unsave item':'Save item'}">${icon('heart',21,data.saved.includes(id))}</button></div>`}${i.photos?.length>1?`<div class="photos">${i.photos.map((p,n)=>`<a href="${E(p)}" target="_blank" rel="noopener" aria-label="Open photo ${n+1}"><img src="${E(p)}" alt="Item photo ${n+1}" width="70" height="70" style="object-fit:cover;border-radius:10px"></a>`).join('')}</div>`:''}`);currentDetail=id;}
function filterSheet(){modal('Find your kind of find.',`<form id="filter-form"><div id="filter-error" role="alert"></div><div class="filter-section"><h3>Price range</h3><div class="price-range"><label><span class="sr-only">Minimum price</span><input name="min" inputmode="decimal" type="number" min="0" step="0.01" placeholder="Min $" value="${E(filters.min)}"></label><span class="muted">to</span><label><span class="sr-only">Maximum price</span><input name="max" inputmode="decimal" type="number" min="0" step="0.01" placeholder="Max $" value="${E(filters.max)}"></label></div></div><div class="filter-section"><h3>Condition</h3>${CONDITIONS.map(c=>`<label class="check-row"><input type="checkbox" name="condition" value="${E(c)}" ${filters.conditions.includes(c)?'checked':''}>${E(c)}</label>`).join('')}</div><div class="filter-footer"><button type="button" class="secondary" data-action="clear-filters">Reset</button><button type="submit" class="primary">Show results ${icon('arrow',17)}</button></div></form>`);}
function post(){draftPhotos=[];modal('Post an item',`<form id="post-form" novalidate><div id="post-error" role="alert"></div><div class="field"><label for="photos">Add photos <span class="muted small">· Optional · Up to 4</span></label><label for="photos" class="photos-label">${icon('camera',27)} Add photos from your phone</label><input class="sr-only" id="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple><p class="small muted" style="margin:9px 0 0">JPG, PNG or WebP · 10 MB max per photo</p><div id="photo-preview" class="photos"></div></div><div class="field"><label for="post-title">Title</label><input id="post-title" name="title" maxlength="80" placeholder="What are you passing on?" required></div><div class="field"><label for="post-description">Description <span class="muted">(optional)</span></label><textarea id="post-description" name="description" maxlength="1500" placeholder="A few details go a long way."></textarea></div><div class="field"><label for="post-price">Price ($)</label><input id="post-price" name="price" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0.00" required></div><div class="field"><label for="post-category">Category</label><select name="category" id="post-category" required><option value="">Choose a category</option>${CATEGORIES.slice(1).map(c=>`<option>${E(c)}</option>`).join('')}</select></div><div class="field"><label>Condition</label><div class="condition-pills" role="group" aria-label="Item condition">${CONDITIONS.map(c=>`<label><input name="condition" type="radio" value="${E(c)}" ${c==='Used'?'checked':''}>${E(c)}</label>`).join('')}</div></div><div class="field"><label for="post-location">Pickup area</label><input id="post-location" name="location" maxlength="80" value="${E(data.profile.location)}" placeholder="Campus or neighborhood"></div><div class="info">Only a demo listing: saved on this device, visible only to you. No item is published to the real marketplace.</div><button type="submit" class="primary block" style="margin-top:20px">Save demo listing ${icon('arrow',17)}</button></form>`);}
function toggleSave(id){if(data.saved.includes(id)){data.saved=data.saved.filter(x=>x!==id);toast('Removed from saved items.');}else{data.saved.push(id);toast('Saved for later.');}persist();render();}
function showThread(id){const t=data.threads.find(x=>x.id===id);if(!t)return;modal('Practice conversation',`<div class="seller" style="border:0;padding-top:0"><div class="icon-btn avatar">${E(t.seller[0])}</div><div><strong>${E(t.seller)}</strong><br><span class="small muted">${E(t.title)}</span></div></div><div class="info">Demo chat. No seller receives these messages.</div><div id="thread-bubbles">${t.messages.map(m=>`<div class="bubble">${E(m)}</div><p class="thread-note">You · Saved locally</p>`).join('')}</div><form class="thread-send" id="message-form" data-id="${E(id)}"><label class="sr-only" for="message">Practice message</label><input id="message" name="message" maxlength="500" placeholder="Is this still available?" required><button class="primary" type="submit" aria-label="Save practice message">${icon('arrow',20)}</button></form>`);}
function info(kind){const contents={about:['Built for a real test drive.',`<p class="muted">This is a working mobile web prototype of Student Exchange. Try browsing, filters, saving items, posting a listing with photos, editing your profile, and practice messaging.</p><div class="info">All marketplace activity is local to this browser. No real login, seller contact, payment, or backend connection is active.</div><p class="install-tip">Your data stays after refreshing when browser storage is available. Private browsing or clearing site data can remove it. ${storageFailed?'Storage is currently unavailable.':''}</p>`],install:['Keep it close.',`<p class="muted"><strong>iPhone / iPad:</strong> Open this link in Safari, tap Share, then Add to Home Screen.</p><p class="muted"><strong>Android:</strong> Open in Chrome, tap the three-dot menu, then Add to Home screen.</p><div class="info">This adds a shortcut to the mobile web prototype. It is not an App Store or Play Store install. An internet connection and access to this private site are required.</div>`],'reset-password':['Password recovery',`<p class="muted">Real account recovery is not connected. Use “Fill demo account” to test login. No password reset email will be sent.</p>`]};modal(contents[kind][0],contents[kind][1]);}
function profile(){modal('Account settings',`<form id="profile-form"><div class="field"><label for="profile-name">Display name</label><input id="profile-name" name="name" maxlength="35" required value="${E(data.profile.name)}"></div><div class="field"><label for="profile-school">Campus</label><select id="profile-school" name="school">${['CU Denver','MSU Denver','Community College of Denver','Other campus'].map(x=>`<option ${data.profile.school===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="profile-location">Default pickup area</label><input id="profile-location" name="location" maxlength="80" required value="${E(data.profile.location)}"></div><p class="info">Local profile only. Campus options are examples and are not verified against the Schools API.</p><button class="primary block" type="submit">Save changes</button></form>`);}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
 if(a==='close')close();else if(a==='enter')enter();else if(a==='login'){clearTimeout(startTimer);screen='login';render();}else if(a==='welcome'){screen='welcome';render();}else if(a==='next'){if(step<2)step++;else screen='login';render();}else if(a==='slide'){step=Number(b.dataset.index);render();}else if(a==='nav'){go(b.dataset.page);}else if(a==='post')post();else if(a==='save')toggleSave(id);else if(a==='detail-save'){toggleSave(id);detail(id);}else if(a==='detail')detail(id);else if(a==='filters')filterSheet();else if(a==='clear-filters'){filters={category:'All',min:'',max:'',conditions:[]};filterSheet();render();}else if(a==='category'){filters.category=b.dataset.category;render();}else if(a==='fill-demo'){document.getElementById('email').value=SAMPLE_EMAIL;document.getElementById('password').value=SAMPLE_PASSWORD;document.getElementById('login-error').innerHTML='';}else if(a==='show-password'){const p=document.getElementById('password');p.type=p.type==='password'?'text':'password';b.textContent=p.type==='password'?'Show':'Hide';b.setAttribute('aria-label',`${b.textContent} password`);}else if(['about','install','reset-password'].includes(a))info(a);else if(a==='profile')profile();else if(a==='logout'){data.session=false;persist();screen='login';render();toast('Logged out of the demo.');}else if(a==='start-thread'){const i=items().find(x=>x.id===id);if(!data.threads.some(x=>x.id===id)){data.threads.push({id,title:i.title,seller:i.seller,messages:[]});persist();}showThread(id);}else if(a==='thread')showThread(id);else if(a==='sold'){const i=data.items.find(x=>x.id===id);i.sold=!i.sold;persist();detail(id);render();toast(i.sold?'Marked as sold in your demo.':'Your demo listing is available again.');}else if(a==='delete'){modal('Remove this demo listing?',`<p class="muted">This removes the item and its photos from this browser.</p><button class="primary block" data-action="confirm-delete" data-id="${E(id)}">Delete demo listing</button>`);}else if(a==='confirm-delete'){data.items=data.items.filter(x=>x.id!==id);data.saved=data.saved.filter(x=>x!==id);persist();close();go('mine');toast('Demo listing deleted.');}else if(a==='remove-photo'){draftPhotos.splice(Number(b.dataset.index),1);photoPreview();}else if(a==='reset'){modal('Start fresh?',`<p class="muted">Remove your demo listings, photos, saved items, and practice messages from this device?</p><button class="primary block" data-action="confirm-reset">Reset my prototype</button>`);}else if(a==='confirm-reset'){try{localStorage.removeItem(KEY);}catch{}data={items:[],saved:[],profile:{name:'Alex',school:'CU Denver',location:'Auraria campus'},threads:[],session:false};close();screen='welcome';step=0;filters={category:'All',min:'',max:'',conditions:[]};query='';render();toast('Ready for a fresh test drive.');}
});
document.addEventListener('submit',e=>{
 const f=e.target;if(!['login-form','filter-form','post-form','profile-form','message-form'].includes(f.id))return;e.preventDefault();const p=Object.fromEntries(new FormData(f));
 if(f.id==='login-form'){const err=validateLogin(p.email,p.password);if(err){document.getElementById('login-error').innerHTML=`<p class="error">${E(err)}</p>`;return;}enter();toast('Welcome to the demo, Alex.');}
 if(f.id==='filter-form'){const min=p.min,max=p.max;const invalid=[min,max].some(x=>x!==''&&(!Number.isFinite(Number(x))||Number(x)<0));if(invalid||(min!==''&&max!==''&&Number(min)>Number(max))){document.getElementById('filter-error').innerHTML='<p class="error">Enter a valid range with minimum no higher than maximum.</p>';return;}filters={...filters,min,max,conditions:new FormData(f).getAll('condition')};close();render();}
 if(f.id==='post-form'){const err=validatePost(p);if(err){const el=document.getElementById('post-error');el.innerHTML=`<p class="error">${E(err)}</p>`;el.scrollIntoView({block:'center'});return;}data.items.unshift({id:(globalThis.crypto?.randomUUID?.()||`local-${Date.now()}-${Math.random().toString(36).slice(2)}`),title:p.title.trim(),description:p.description.trim(),price:Number(Number(p.price).toFixed(2)),category:p.category,condition:p.condition,location:p.location.trim(),seller:data.profile.name,own:true,photos:[...draftPhotos],kind:'other',tone:'sage',age:'Just now',sold:false});const saved=persist();close();go('mine');toast(saved?'Demo listing saved on this device.':'Listing created for this session only.');}
 if(f.id==='profile-form'){if(!p.name.trim()||!p.location.trim()){toast('Enter a name and pickup area.');return;}data.profile={name:p.name.trim(),school:p.school,location:p.location.trim()};const saved=persist();close();render();toast(saved?'Profile updated on this device.':'Profile updated for this session.');}
 if(f.id==='message-form'){const text=p.message.trim();if(!text)return;const t=data.threads.find(x=>x.id===f.dataset.id);t.messages.push(text);persist();showThread(t.id);toast('Practice message saved. Nothing was sent.');}
});
function photoPreview(){document.getElementById('photo-preview').innerHTML=draftPhotos.map((p,i)=>`<div class="thumb"><img src="${p}" alt="Selected photo ${i+1}"><button type="button" data-action="remove-photo" data-index="${i}" aria-label="Remove photo ${i+1}">×</button></div>`).join('');}
document.addEventListener('change',async e=>{
 if(e.target.id!=='photos')return;
 const input=e.target,form=input.closest('form'),submit=form.querySelector('[type=submit]'),currentPhotos=draftPhotos;
 const files=Array.from(input.files);submit.disabled=true;input.disabled=true;
 try{for(const file of files){
  if(draftPhotos.length>=4){toast('You can add up to 4 photos.');break;}
  if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('Choose JPG, PNG, or WebP under 10 MB.');continue;}
  try{const p=await compress(file);if(!form.isConnected||draftPhotos!==currentPhotos)return;draftPhotos.push(p);photoPreview();}
  catch{toast('Could not read that photo. Try a JPG or PNG.');}
 }}finally{if(form.isConnected){submit.disabled=false;input.disabled=false;input.value='';}}
});
function compress(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{try{const scale=Math.min(1,800/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.7));}catch(e){reject(e);}finally{URL.revokeObjectURL(url);}};image.onerror=()=>{URL.revokeObjectURL(url);reject();};image.src=url;});}
render();startTimer=setTimeout(()=>{screen=data.session?'app':'welcome';render();},550);
